+                            "greater than zero. Check yaml file.");
+    return false;
+  }
+  if (ros_parameters_.collision_proximity_threshold < 0.)
+  {
+    ROS_WARN_NAMED(LOGNAME, "Parameter 'collision_proximity_threshold' should be "
