+      for (unsigned int i = 0; i < degree_; ++i)
+      {
+        // make sure degree lies between minDegree_ and maxDegree_
+        children_[i]->degree_ =
+            std::min(std::max((unsigned int)((degree_ * children_[i]->data_.size()) / data_.size()), gnat.minDegree_),
+                     gnat.maxDegree_);
