+        if (children_[i]->minRadius_ >= std::numeric_limits<double>::infinity())
+          children_[i]->minRadius_ = children_[i]->maxRadius_ = 0.;
+      }
+      // this does more than clear(); it also sets capacity to 0 and frees the memory
+      std::vector<_T> tmp;
+      data_.swap(tmp);
